68	{
69		if (!HasAuthority())
70		{
71			return nullptr;
72		}
73	
74		const UCL9GameInstance* GameInstance = GetGameInstance<UCL9GameInstance>();
75		const UCL9DefRegistry* Registry = GameInstance ? GameInstance->GetDefRegistry() : nullptr;
76		const UCL9ItemDef* Def = Registry ? Registry->FindItem(ItemAlias, ItemSubAlias) : nullptr;
77		if (Def == nullptr)
78		{
79			UE_LOG(LogCL9, Error, TEXT("SpawnItem: item row '%s'/'%s' is missing or broken — nothing spawned."),
80				*ItemAlias.ToString(), *ItemSubAlias.ToString());
81			return nullptr;
82		}
83	
84		UClass* SpawnClass = ItemClass;
85		if (!Def->ActorClass.IsNull())
86		{
87			UClass* DedicatedClass = Def->ActorClass.LoadSynchronous();
88			if (DedicatedClass != nullptr && DedicatedClass->IsChildOf(ACL9Item::StaticClass()))
89			{
90				SpawnClass = DedicatedClass;
91			}
92			else
93			{
94				UE_LOG(LogCL9, Error, TEXT("SpawnItem: '%s' ActorClass does not derive from ACL9Item — using the shared BP."), *ItemAlias.ToString());
95			}
96		}
97		if (SpawnClass == nullptr)
98		{
99			UE_LOG(LogCL9, Error, TEXT("SpawnItem: no item class — assign ItemClass in the game mode BP."));
100			return nullptr;
101		}
102	
103		FActorSpawnParameters SpawnParameters;
104		SpawnParameters.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;
105		ACL9Item* Item = GetWorld()->SpawnActor<ACL9Item>(SpawnClass, Transform, SpawnParameters);
106		if (Item != nullptr)
107		{
108			// SetAlias가 호스트에서 LoadData를 바로 돌려 값을 굴린다 — 보존값은 그 뒤에 덮어써야 남는다
109			Item->SetAlias(ItemAlias, ItemSubAlias);
110			if (PresetValue >= 0)
111			{
112				Item->HostSetValue(PresetValue);
113			}
114		}
115		return Item;
116	}
