164	void ACL9GameMode::StartNight()
165	{
166		ACL9GameState* CL9GameState = GetGameState<ACL9GameState>();
167		if (CL9GameState == nullptr || CL9GameState->GetPhase() != ECL9NightPhase::Lobby)
168		{
169			UE_LOG(LogCL9, Warning, TEXT("StartNight: only the lobby can start a night."));
170			return;
171		}
172	
173		// 새벽이 끝났다 — 지난 정산 결과는 이 밤부터 유효하지 않다(새벽 화면이 그것으로 판단한다)
174		CL9GameState->ClearLastSettlement();
175	
176		const UCL9RulesDef* Rules = GetRules();
177		if (Rules == nullptr)
178		{
179			UE_LOG(LogCL9, Error, TEXT("StartNight: no usable rules row — night not started."));
180			return;
181		}
182	
183		// 날짜 곡선이 규칙의 밤 길이와 사이트의 개체 수를 조정한다(docs/plan/data/progression.md);
184		// progression 애셋이 없으면 보정이 없다는 뜻이고, site가 없으면 그날 밤은 텅 빈다.
185		const int32 Day = CL9GameState->GetCurrentDay();
186		const UCL9ProgressionDef* Progression = GetProgression();
187		const bool bNoBlackout = Progression != nullptr && Progression->IsBlackoutDisabled(Day);
188	
189		const UCL9GameInstance* GameInstance = GetGameInstance<UCL9GameInstance>();
190		const UCL9DefRegistry* Registry = GameInstance ? GameInstance->GetDefRegistry() : nullptr;
191		const UCL9SiteDef* Site = Registry ? Registry->FindSite(ActiveSiteAlias) : nullptr;
192		if (Site == nullptr)
193		{
194			UE_LOG(LogCL9, Error, TEXT("StartNight: site row '%s' is missing or broken — no animals or ingredients tonight (set the row's Level, or DefaultSiteAlias in the game mode BP)."),
195				*ActiveSiteAlias.ToString());
196		}
197	
198		// 밤 시계는 사이트가 덮어쓸 수 있다 — 0이면 규칙의 전역값 (docs/plan/data/site.md 밤 시계)
199		const float NightLength = (Site ? UCL9SiteDef::OrRule(Site->NightLength, Rules->NightLength) : Rules->NightLength)
200			* (Progression ? Progression->NightLengthAt(Day) : 1.f);
201		const float DarkBase = Site ? UCL9SiteDef::OrRule(Site->DarkBase, Rules->DarkBase) : Rules->DarkBase;
202		const float DarkMin = Site ? UCL9SiteDef::OrRule(Site->DarkMin, Rules->DarkMin) : Rules->DarkMin;
203		const float Danger = (Site ? Site->BaseDanger : 1.f) * (Progression ? Progression->DangerAt(Day) : 1.f);
204		CL9GameState->SetSiteAndDanger(Site ? Site->Alias : NAME_None, Danger);
205	
206		// 로비가 이미 오늘 밤의 미로를 세워뒀다(2026-09-06 결정 — 로비부터 오늘 밤 미로); 어쩌다
207		// 미로가 없는 월드만 지금 하나 받는다. 공유되는 것은 시드뿐이다 — 모든 머신이
208		// 그 시드로부터 같은 미로를 깐다(docs/systems/map.md).
209		if (CL9GameState->GetMapSeed() == 0)
210		{
211			CL9GameState->SetSiteMap(RollMapSeed(ForcedMapSeed));
212		}
213	
214		CL9GameState->StartNightClock(NightLength, DarkBase, DarkMin, bNoBlackout);
215		CL9GameState->SetPhase(ECL9NightPhase::Night);
216		GetWorldTimerManager().SetTimer(NightExpiryHandle, this, &ACL9GameMode::EndNight, NightLength);
217	
218		UE_LOG(LogCL9, Log, TEXT("Night %d at '%s' started — %.0fs to dawn, blackout %s, danger ×%.2f."),
219			Day, *ActiveSiteAlias.ToString(), NightLength, bNoBlackout ? TEXT("off (day override)") : *FString::Printf(TEXT("base %.0fs"), DarkBase), Danger);
220	
221		if (Site != nullptr)
222		{
223			SpawnNightPopulation(*Site, Progression, Day);
224		}
225	}
226	
227	void ACL9GameMode::EndNight()
228	{
229		ACL9GameState* CL9GameState = GetGameState<ACL9GameState>();
230		if (CL9GameState == nullptr || CL9GameState->GetPhase() != ECL9NightPhase::Night)
231		{
232			UE_LOG(LogCL9, Warning, TEXT("EndNight: no night is running."));
233			return;
234		}
235	
236		GetWorldTimerManager().ClearTimer(NightExpiryHandle);
237		CL9GameState->SetPhase(ECL9NightPhase::Dawn);
238		UE_LOG(LogCL9, Log, TEXT("Night %d over — dawn."), CL9GameState->GetCurrentDay());
239	
240		// DawnLength는 아직 정해지지 않았다(0) — 값이 정해지기 전까지 새벽은 그냥 곧바로 지나간다.
241		const UCL9RulesDef* Rules = GetRules();
242		const float DawnLength = Rules ? Rules->DawnLength : 0.f;
243		if (DawnLength > 0.f)
244		{
245			GetWorldTimerManager().SetTimer(DawnHandle, this, &ACL9GameMode::EnterLobby, DawnLength);
246		}
247		else
248		{
249			EnterLobby();
250		}
251	}
252	
253	void ACL9GameMode::EnterLobby()
254	{
255		ACL9GameState* CL9GameState = GetGameState<ACL9GameState>();
256		if (CL9GameState == nullptr)
257		{
258			return;
259		}
