// -- 밤 시계 --

/** 밤 길이, 초 단위 — 시간이 다 되면 새벽 실패가 된다 */
UPROPERTY(EditAnywhere, BlueprintReadOnly, Category="Night")
float NightLength = 245.f;

/** 정전까지 걸리는 기본 시간, 초 단위 */
UPROPERTY(EditAnywhere, BlueprintReadOnly, Category="Night")
float DarkBase = 185.f;

/** 항아리 반납 한 번이 정전 시각을 앞당기는 시간, 초 단위 */
UPROPERTY(EditAnywhere, BlueprintReadOnly, Category="Night")
float DarkAccel = 4.f;

/** 가능한 가장 이른 정전 시각, 초 단위 */
UPROPERTY(EditAnywhere, BlueprintReadOnly, Category="Night")
float DarkMin = 125.f;

/** 새벽 화면 길이, 초 단위 — 미정 */
UPROPERTY(EditAnywhere, BlueprintReadOnly, Category="Night")
float DawnLength = 0.f;

// -- 던지기와 소지 --

