299	void ACL9Monster::TickHitFeel()
300	{
301		if (MeshComponent == nullptr)
302		{
303			return;
304		}
305	
306		const UCL9GameInstance* GameInstance = GetGameInstance<UCL9GameInstance>();
307		const UCL9DefRegistry* Registry = GameInstance ? GameInstance->GetDefRegistry() : nullptr;
308		const UCL9RulesDef* Rules = Registry ? Registry->GetRules() : nullptr;
309		if (Rules == nullptr)
310		{
311			return;
312		}
313	
314		// TickHitFlash 와 같은 "맞은 직후" 창 — 그 창의 상승 에지가 타격의 순간이다. 창 안에서 상태 시각만 바뀌면 경직 중에
315		// 다시 맞은 것(둘이 동시에 때림)이라 그것도 에지다
316		const bool bStruckState = State == ECL9MonsterState::Stun || State == ECL9MonsterState::Dead;
317		const float Elapsed = GetStateElapsed();
318		const bool bInWindow = bStruckState && Elapsed < Rules->HitFlashTime;
319		const bool bEdge = bInWindow && (!bHitFeelInWindow || StateStartServerTime != LastSeenStateStartTime);
320		const bool bPrimed = bHitFeelPrimed;
321		bHitFeelPrimed = true;
322		bHitFeelInWindow = bInWindow;
323		LastSeenStateStartTime = StateStartServerTime;
324	
325		// 접속 직후·스폰 직후의 첫 틱은 기준값만 적는다 — 이미 지나간 타격을 되풀이하지 않는다
326		if (bEdge && bPrimed)
327		{
328			const bool bDeath = State == ECL9MonsterState::Dead;
329			const FVector Center = MeshComponent->Bounds.Origin;
330			CL9Sound::PlayAt(this, CL9SoundNames::Hit, Center);
331			if (bDeath)
332			{
333				CL9Sound::PlayAt(this, CL9SoundNames::MonsterDeath, Center);
334			}
335			SpawnHitPuff(bDeath);
336		}
337	
338		// 히트스톱: 진입 뒤 HitStopTime 동안 메시가 그 프레임에 머문다. 판정·이동·AI는 그대로 흐른다 (전역 시간 지연 금지)
339		const bool bWantStop = bStruckState && Elapsed < Rules->HitStopTime;
340		if (bWantStop != bHitStopOn)
341		{
342			bHitStopOn = bWantStop;
343			MeshComponent->bPauseAnims = bWantStop;
344		}
345	}
