347	void ACL9Monster::TickStateSounds()
348	{
349		// 전이 = 상태가 바뀌었거나 같은 상태의 시작 시각이 바뀜(연속 예고처럼 같은 상태로 다시 들어옴). 창(elapsed)이 아니라 전이라
350		// 20Hz 복제가 늦게 와도 한 번은 반드시 잡힌다
351		const bool bPrimed = bStateSoundPrimed;
352		const bool bTransition = State != LastSoundState || StateStartServerTime != LastSoundStateStartTime;
353		bStateSoundPrimed = true;
354		LastSoundState = State;
355		LastSoundStateStartTime = StateStartServerTime;
356	
357		// 접속·스폰 직후의 첫 틱은 기준값만 — 이미 지나간 예고·잡기를 되풀이하지 않는다
358		if (!bPrimed || !bTransition || MeshComponent == nullptr)
359		{
360			return;
361		}
362	
363		const FVector Center = MeshComponent->Bounds.Origin;
364		switch (State)
365		{
366		case ECL9MonsterState::Pounce:
367			CL9Sound::PlayAt(this, CL9SoundNames::MonsterPounce, Center);
368			break;
369		case ECL9MonsterState::Catch:
